  const state = generateOAuthState(originHeader);
  const clientId =
    process.env.GOOGLE_CLIENT_ID ||
    process.env.VITE_GOOGLE_CLIENT_ID ||
    '737774141986-jqmalq9e63isp91q27jd9ghvebc0i22i.apps.googleusercontent.com';
