  // 2.3 Verificação de Papel (Role) na Matriz de Autorização
  const allowedRoles = routeDef.allowedRoles || [];
  const isRoleAllowed =
    userRole === USER_ROLES.SUPERADMIN || allowedRoles.includes(userRole);

