                            <span className={ciCdSimResult.details.sca.status === "PASSED" ? "text-emerald-400" : "text-rose-400"}>
                              {ciCdSimResult.details.sca.status === "PASSED" ? "Aprovado (0 CVEs)" : "✗ Falha: CVE High/Critical"}
                            </span>
