  if (payload.exp < nowSeconds - JWT_SECURITY_POLICY.CLOCK_TOLERANCE_SECONDS) {
    return { valid: false, ttlSeconds, error: "Token expirado." };
  }

  return { valid: true, ttlSeconds };
