      expect(response.status).toBe(400);
      expect(response.body.code).toBe("SCHEMA_VALIDATION_ERROR");
      expect(response.body.details).toEqual(
        expect.arrayContaining([
          expect.objectContaining({
            field: "body.email",
          }),
        ])
      );
